// Embeds skills/charcoal/SKILL.md into the CLI source before it is compiled,
// so `ch skill` works from the single-file binary and always matches its version.
const fs = require('fs');
const path = require('path');

const source = path.join(__dirname, '..', '..', '..', 'skills', 'charcoal', 'SKILL.md');
const target = path.join(__dirname, '..', 'src', 'generated', 'skill.ts');
const content = [
  '/* eslint-disable */',
  '// Generated by scripts/embed_skill.js from skills/charcoal/SKILL.md; do not edit.',
  `export const SKILL_MD = ${JSON.stringify(fs.readFileSync(source, 'utf-8'))};`,
  '',
].join('\n');

if (!fs.existsSync(target) || fs.readFileSync(target, 'utf-8') !== content) {
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content);
}
